(()=>{const g=__game;const U={};U.cam=()=>{const sc=g.ext.wp5Scene();let c=null;sc.traverse(o=>{if(o.isPerspectiveCamera)c=o});c.updateMatrixWorld();return c};
U.V=()=>U.cam().position.constructor;
U.ndc=(p)=>{const c=U.cam();const V=U.V();return new V(p[0],p[1],p[2]).project(c)};
U.skin=(root,each)=>{root.updateMatrixWorld(true);let m=null;root.traverse(o=>{if(o.isSkinnedMesh&&!m)m=o});if(!m)return;const pos=m.geometry.getAttribute('position'),si=m.geometry.getAttribute('skinIndex');const V=U.V();const v=new V();const third=(m.skeleton.bones[24]?m.skeleton.bones[24].scale.x:0)>0.01;for(let i=0;i<pos.count;i++){const b=si.getX(i);if(b>=27||(b>=24&&!third))continue;v.fromBufferAttribute(pos,i);m.applyBoneTransform(i,v);v.applyMatrix4(m.matrixWorld);each(v,b)}};
U.box=()=>{const sc=g.ext.wp5Scene();const p=sc.getObjectByName('player');const c=U.cam();const b=[9,9,-9,-9];if(!p||!p.visible)return b;U.skin(p,(v)=>{const q=v.clone().project(c);if(q.z>1)return;b[0]=Math.min(b[0],q.x);b[1]=Math.min(b[1],q.y);b[2]=Math.max(b[2],q.x);b[3]=Math.max(b[3],q.y)});return b.map(x=>+x.toFixed(3))};
